"""Billing for orders. Rate lookups are billed, so the charge is remembered."""
import rates


class OrderBill:
    def __init__(self):
        self._orders = []
        self._charge = None

    def add(self, order):
        """Add one order to the bill."""
        self._orders.append(order)

    def charge(self):
        """Return the total charge: amount times the rate for each order's customer.

        The result is remembered: asking again without adding anything makes no new rate lookups.
        """
        if self._charge is None:
            self._charge = sum(x.amount * rates.rate_for(x.customer) for x in self._orders)
        return self._charge

